-- 0046: the product owner's spreadsheet of 2026-11-27 (brain_region_new_platform.xlsx).
--
--   * Left DLPFC and left orbitofrontal gain their diagonals: continuous RTL, TRDBL; intervals LTR, BLDTR.
--   * Brodmann areas: Parietal is BA39 and BA40 only; Inferior parietal is BA7 only. BA1, BA2, BA3, BA43 and BA5 no
--     longer belong to a sub-lobe (they stay as tags for videos). A game step filtered by one of them is first
--     re-pointed at the sub-lobe it resolved to, so it keeps running with the same settings.
--   * Everything else in the spreadsheet equals what 0044 and 0045 stored (left basal ganglia direct pathway: see 0045).
--
-- Data only. Generated by settingRevisionSql() and areaUnlinkSql(); a test checks this file against them.

UPDATE app.region_setting s SET bg_temperature = 'warm', bg_types = ARRAY['textured']::text[], motion = '[{"movement_types":[0,3],"directions":["rtl","trdbl"]},{"movement_types":[1,4],"directions":["ltr","bldtr"]}]'::jsonb, target_locations = ARRAY['E', 'SE', 'S']::text[], rotation = 'ccw', clinical_status = 'draft', revision = s.revision + 1, updated_at = now() FROM app.brain_region b WHERE b.id = s.sublobe_id AND b.path = 'left.frontal.dlpfc';
UPDATE app.region_setting s SET bg_temperature = 'warm', bg_types = ARRAY['solid']::text[], motion = '[{"movement_types":[0,3],"directions":["rtl","trdbl"]},{"movement_types":[1,4],"directions":["ltr","bldtr"]}]'::jsonb, target_locations = ARRAY['E', 'NE', 'N']::text[], rotation = 'ccw', clinical_status = 'draft', revision = s.revision + 1, updated_at = now() FROM app.brain_region b WHERE b.id = s.sublobe_id AND b.path = 'left.frontal.orbitofrontal';

UPDATE app.template_step t SET region_id = a.sublobe_id FROM app.brain_region a WHERE a.path = 'left.parietal.ba1' AND a.sublobe_id IS NOT NULL AND t.region_id = a.id;
